package com.terpinheimer.map;

import java.io.IOException;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Async POST to a clan-hosted live map API. Compatible with the pattern used by the
 * <a href="https://github.com/s0lved/goblin-scape-clan-plugin">Goblin Scape clan plugin</a>:
 * {@code POST {baseUrl}/post}, JSON body, {@code Authorization} header set to the shared key.
 */
@Singleton
public class LiveMapService
{
	private static final Logger log = LoggerFactory.getLogger(LiveMapService.class);
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	private final OkHttpClient http;

	@Inject
	LiveMapService(OkHttpClient http)
	{
		this.http = http;
	}

	public static String buildPostUrl(String baseUrl)
	{
		if (baseUrl == null)
		{
			return null;
		}
		String url = baseUrl.trim();
		if (url.isEmpty())
		{
			return null;
		}
		if (url.endsWith("/"))
		{
			return url + "post";
		}
		return url + "/post";
	}

	public void postPlayerLocation(String postUrl, String authorizationKey, String jsonBody)
	{
		if (postUrl == null || authorizationKey == null || authorizationKey.trim().isEmpty()
			|| jsonBody == null || jsonBody.isEmpty())
		{
			return;
		}
		Request req = new Request.Builder()
			.url(postUrl)
			.header("Authorization", authorizationKey.trim())
			.post(RequestBody.create(JSON, jsonBody))
			.build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("Live map POST failed: {}", e.getMessage());
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (!r.isSuccessful())
					{
						log.debug("Live map POST HTTP {}", r.code());
					}
				}
			}
		});
	}
}

package com.terpinheimer.map;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.terpinheimer.TerpinheimerConfig;
import com.terpinheimer.site.TerpinheimerRemoteConfigService;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.Varbits;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameTick;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Pushes the local player's world position on a throttled schedule so a clan website can plot it,
 * following the same client-side approach as the Goblin Scape clan plugin.
 */
@Singleton
public class LiveMapEventHandler
{
	private static final Logger log = LoggerFactory.getLogger(LiveMapEventHandler.class);

	private final Client client;
	private final TerpinheimerConfig config;
	private final TerpinheimerRemoteConfigService remoteConfigService;
	private final Gson gson;
	private final LiveMapService liveMapService;

	private int tickCounter;

	@Inject
	LiveMapEventHandler(
		Client client,
		TerpinheimerConfig config,
		TerpinheimerRemoteConfigService remoteConfigService,
		Gson gson,
		LiveMapService liveMapService)
	{
		this.client = client;
		this.config = config;
		this.remoteConfigService = remoteConfigService;
		this.gson = gson;
		this.liveMapService = liveMapService;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (!config.liveMapEnabled())
		{
			return;
		}
		if (config.liveMapEventHide())
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		int interval = Math.max(1, config.liveMapIntervalTicks());
		tickCounter++;
		if (tickCounter < interval)
		{
			return;
		}
		tickCounter = 0;

		String base = remoteConfigService.getLiveMapApiBase();
		String key = config.clanSecret();
		String postUrl = LiveMapService.buildPostUrl(base);
		if (postUrl == null || !isValidHttpsBase(base) || key == null || key.trim().isEmpty())
		{
			return;
		}

		try
		{
			if (!config.liveMapSendInWilderness() && client.getVarbitValue(Varbits.IN_WILDERNESS) != 0)
			{
				return;
			}

			Player player = client.getLocalPlayer();
			if (player == null)
			{
				return;
			}
			LocalPoint local = player.getLocalLocation();
			if (local == null)
			{
				return;
			}
			WorldPoint worldPoint = WorldPoint.fromLocalInstance(client, local);
			if (worldPoint == null)
			{
				return;
			}

			String displayName = Text.removeTags(player.getName());
			if (displayName == null || displayName.isBlank())
			{
				return;
			}

			JsonObject waypoint = new JsonObject();
			waypoint.addProperty("x", worldPoint.getX());
			waypoint.addProperty("y", worldPoint.getY());
			waypoint.addProperty("plane", worldPoint.getPlane());

			JsonObject root = new JsonObject();
			root.addProperty("name", displayName);
			root.add("waypoint", waypoint);
			root.addProperty("title", clanTitleForPlayer(displayName));
			root.addProperty("world", client.getWorld());

			liveMapService.postPlayerLocation(postUrl, key, gson.toJson(root));
		}
		catch (RuntimeException e)
		{
			log.debug("Terpinheimer: live map tick skipped ({})", e.toString());
		}
	}

	private static boolean isValidHttpsBase(String url)
	{
		if (url == null)
		{
			return false;
		}
		String t = url.trim();
		return t.startsWith("https://") && t.length() > "https://x".length();
	}

	private String clanTitleForPlayer(String playerName)
	{
		try
		{
			ClanSettings settings = client.getClanSettings();
			if (settings == null)
			{
				return "";
			}
			ClanMember member = settings.findMember(playerName);
			if (member == null)
			{
				member = settings.findMember(Text.standardize(playerName));
			}
			if (member == null)
			{
				return "";
			}
			ClanRank rank = member.getRank();
			if (rank == null)
			{
				return "";
			}
			ClanTitle title = settings.titleForRank(rank);
			if (title == null)
			{
				return "";
			}
			String name = title.getName();
			return name != null ? name : "";
		}
		catch (RuntimeException e)
		{
			return "";
		}
	}
}

package com.terpinheimer.site;

import java.io.IOException;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Async HTTPS POST of collection log / chronicle payload to the clan website.
 * <p>
 * For {@code terpinheimercc.com}, a plain RuneLite sync secret is sent in JSON as {@code syncToken} and
 * mirrored on {@code X-Sync-Token} / {@code Sync-Token} when no {@code Authorization} header is sent.
 * An {@code Authorization: Bearer …} header is added only when you paste a session JWT (or a value that
 * looks like a JWT). Other hosts still receive the secret as a raw {@code Authorization} value.
 */
@Singleton
public class ClogSiteSyncService
{
	private static final Logger log = LoggerFactory.getLogger(ClogSiteSyncService.class);
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final int CHAT_DETAIL_MAX = 140;

	private final OkHttpClient http;
	private final Client client;
	private final ClientThread clientThread;

	@Inject
	ClogSiteSyncService(OkHttpClient http, Client client, ClientThread clientThread)
	{
		this.http = http;
		this.client = client;
		this.clientThread = clientThread;
	}

	/**
	 * Same as {@link #postClogJsonAsync(String, String, String, boolean)} with no in-game chat for the result
	 * (logout / hop sync).
	 */
	public void postClogJsonAsync(String httpsPostUrl, String authorizationSecret, String jsonBody)
	{
		postClogJsonAsync(httpsPostUrl, authorizationSecret, jsonBody, false);
	}

	/**
	 * Same HTTPS + auth rules as collection log sync, for other JSON POSTs (e.g. clan roster snapshot).
	 */
	public void postSiteJsonAsync(String httpsPostUrl, String authorizationSecret, String jsonBody)
	{
		postSiteJsonAsync(httpsPostUrl, authorizationSecret, jsonBody, false);
	}

	/**
	 * @param notifyChat when true, posts brief game chat when the request starts and finishes (manual roster POST).
	 */
	public void postSiteJsonAsync(String httpsPostUrl, String authorizationSecret, String jsonBody, boolean notifyChat)
	{
		postJsonToSite(httpsPostUrl, authorizationSecret, jsonBody, notifyChat ? SiteSyncChat.ROSTER : SiteSyncChat.NONE);
	}

	/**
	 * POST clan event attendance report to the website (manual from Clan Event tracker).
	 */
	public void postAttendanceJsonAsync(String httpsPostUrl, String authorizationSecret, String jsonBody)
	{
		postJsonToSite(httpsPostUrl, authorizationSecret, jsonBody, SiteSyncChat.ATTENDANCE);
	}

	/**
	 * @param notifyChat when true, posts brief game chat when the request finishes (manual sync from UI).
	 */
	public void postClogJsonAsync(String httpsPostUrl, String authorizationSecret, String jsonBody, boolean notifyChat)
	{
		postJsonToSite(httpsPostUrl, authorizationSecret, jsonBody, notifyChat ? SiteSyncChat.COLLECTION_LOG : SiteSyncChat.NONE);
	}

	private void postJsonToSite(String httpsPostUrl, String authorizationSecret, String jsonBody, SiteSyncChat syncChat)
	{
		if (httpsPostUrl == null || httpsPostUrl.trim().isEmpty()
			|| authorizationSecret == null || authorizationSecret.trim().isEmpty()
			|| jsonBody == null || jsonBody.isEmpty())
		{
			return;
		}
		String trimmedIn = httpsPostUrl.trim();
		String url = normalizeSitePostUrl(trimmedIn);
		if (!url.equals(trimmedIn))
		{
			log.info("Terpinheimer: normalized a legacy API path in your sync URL. Using: {}", url);
		}
		if (!url.startsWith("https://"))
		{
			return;
		}
		if (syncChat.notify)
		{
			chat(ChatMessageType.CONSOLE, syncChat.pendingMessage);
		}
		Request.Builder rb = new Request.Builder()
			.url(url)
			.header("Content-Type", "application/json; charset=utf-8")
			.post(RequestBody.create(JSON, jsonBody));
		String secretTrimmed = authorizationSecret.trim();
		String auth = authorizationHeaderValue(url, secretTrimmed);
		if (auth != null && !auth.isEmpty())
		{
			rb.header("Authorization", auth);
		}
		else if (isTerpinheimerClanSite(url.toLowerCase(Locale.ROOT)))
		{
			// Some stacks read sync auth from headers before JSON; harmless if ignored.
			rb.header("X-Sync-Token", secretTrimmed);
			rb.header("Sync-Token", secretTrimmed);
		}
		Request req = rb.build();
		http.newCall(req).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				String msg = e.getMessage() != null ? e.getMessage() : e.getClass().getSimpleName();
				log.warn("Clog site sync POST failed: {}", msg);
				if (syncChat.notify)
				{
					chat(ChatMessageType.CONSOLE, syncChat.failNetworkPrefix + truncate(msg));
				}
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response r = response)
				{
					if (r.isSuccessful())
					{
						log.debug("Clog site sync POST OK {}", r.code());
						if (syncChat.notify)
						{
							chat(ChatMessageType.CONSOLE, syncChat.successMessage);
						}
						return;
					}
					String detail = httpErrorDetail(r);
					log.warn("Clog site sync POST HTTP {} {}", r.code(), detail);
					if (syncChat.notify)
					{
						chat(ChatMessageType.CONSOLE,
							syncChat.failHttpPrefix + r.code() + "): " + truncate(detail));
						if (syncChat == SiteSyncChat.COLLECTION_LOG && r.code() == 500)
						{
							chat(ChatMessageType.CONSOLE,
								"Clog 500: server could not save. Check My profile RSN matches in-game exactly, or check site logs.");
						}
						if (syncChat == SiteSyncChat.ROSTER && r.code() == 404)
						{
							chat(ChatMessageType.CONSOLE,
								"Roster 404: that host has no POST handler for this path yet (common on local dev). Add the API route on the site or set “Clan roster sync API” to a URL where it exists.");
						}
						if (syncChat == SiteSyncChat.ATTENDANCE && r.code() == 404)
						{
							chat(ChatMessageType.CONSOLE,
								"Attendance 404: that host has no POST handler for this path yet. Set Clan event attendance → Event attendance sync API to a URL where it exists.");
						}
					}
				}
			}
		});
	}

	private enum SiteSyncChat
	{
		NONE(false, "", "", "", ""),
		COLLECTION_LOG(true,
			"Sending collection log to clan site…",
			"Collection log sync succeeded. Refresh the site if tiles look stale.",
			"Collection log sync failed (network): ",
			"Collection log sync failed (HTTP "),
		ROSTER(true,
			"Posting clan roster to site…",
			"Clan roster sync succeeded. Refresh the site if the roster looks stale.",
			"Clan roster sync failed (network): ",
			"Clan roster sync failed (HTTP "),
		ATTENDANCE(true,
			"Posting clan event attendance to site…",
			"Event attendance posted to the website.",
			"Event attendance post failed (network): ",
			"Event attendance post failed (HTTP ");

		private final boolean notify;
		private final String pendingMessage;
		private final String successMessage;
		private final String failNetworkPrefix;
		/** Appends status code and detail, e.g. {@code failHttpPrefix + "404): " + detail}. */
		private final String failHttpPrefix;

		SiteSyncChat(boolean notify, String pendingMessage, String successMessage,
			String failNetworkPrefix, String failHttpPrefix)
		{
			this.notify = notify;
			this.pendingMessage = pendingMessage;
			this.successMessage = successMessage;
			this.failNetworkPrefix = failNetworkPrefix;
			this.failHttpPrefix = failHttpPrefix;
		}
	}

	private static String httpErrorDetail(Response r)
	{
		ResponseBody body = r.body();
		if (body == null)
		{
			return r.message() != null ? r.message() : "";
		}
		try
		{
			String raw = body.string();
			return raw != null ? raw.trim() : "";
		}
		catch (IOException e)
		{
			return r.message() != null ? r.message() : "";
		}
	}

	private void chat(ChatMessageType type, String message)
	{
		clientThread.invokeLater(() ->
			client.addChatMessage(type, "Terpinheimer", message, "Terpinheimer"));
	}

	private static String truncate(String s)
	{
		if (s == null || s.isEmpty())
		{
			return "";
		}
		String oneLine = s.replace('\n', ' ').replace('\r', ' ');
		return oneLine.length() <= CHAT_DETAIL_MAX ? oneLine : oneLine.substring(0, CHAT_DETAIL_MAX) + "…";
	}

	/**
	 * Legacy RuneLite docs used {@code /api/runelite/clog-sync} and {@code /api/runelite/roster-sync}, which are
	 * not registered on Terpinheimer clan hosts (404). Rewrites to {@code /api/clog/sync} and
	 * {@code /api/clan/roster/sync} so saved profiles keep working.
	 */
	static String normalizeSitePostUrl(String trimmedHttpsUrl)
	{
		if (trimmedHttpsUrl == null || trimmedHttpsUrl.isEmpty())
		{
			return trimmedHttpsUrl;
		}
		String low = trimmedHttpsUrl.toLowerCase(Locale.ROOT);
		if (!isTerpinheimerClanSite(low))
		{
			return trimmedHttpsUrl;
		}
		String u = trimmedHttpsUrl;
		if (low.contains("/api/runelite/clog-sync"))
		{
			u = u.replace("/api/runelite/clog-sync", "/api/clog/sync");
			low = u.toLowerCase(Locale.ROOT);
		}
		if (low.contains("/api/runelite/roster-sync"))
		{
			u = u.replace("/api/runelite/roster-sync", "/api/clan/roster/sync");
		}
		return u;
	}

	private static boolean isTerpinheimerClanSite(String urlLower)
	{
		return urlLower.contains("terpinheimercc.com") || urlLower.contains("terpinheimercc.onrender.com");
	}

	/**
	 * terpinheimercc.com: plain {@code RUNELITE_CLOG_SYNC_SECRET} values must not be sent as fake
	 * {@code Bearer} tokens (middleware may reject before reading JSON {@code syncToken}). Session JWTs
	 * use {@code Bearer …} in config. Other hosts keep the legacy raw {@code Authorization} header.
	 *
	 * @return value for {@code Authorization}, or {@code null} to omit the header
	 */
	static String authorizationHeaderValue(String normalizedHttpsUrl, String secretTrimmed)
	{
		if (secretTrimmed.regionMatches(true, 0, "Bearer ", 0, 7))
		{
			return secretTrimmed;
		}
		if (!isTerpinheimerClanSite(normalizedHttpsUrl.toLowerCase(Locale.ROOT)))
		{
			return secretTrimmed;
		}
		if (looksLikeJwt(secretTrimmed))
		{
			return "Bearer " + secretTrimmed;
		}
		return null;
	}

	private static boolean looksLikeJwt(String s)
	{
		if (s == null)
		{
			return false;
		}
		String t = s.trim();
		if (t.length() < 20)
		{
			return false;
		}
		int dots = 0;
		for (int i = 0; i < t.length(); i++)
		{
			if (t.charAt(i) == '.')
			{
				dots++;
			}
		}
		return dots >= 2;
	}
}

package com.terpinheimer.site;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import com.terpinheimer.TerpinheimerConfig;
import com.terpinheimer.clan.ClanMemberRankDisplay;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanRank;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.clan.ClanTitle;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

/**
 * JSON body for {@code POST} to the clan website roster / rank-ups endpoint.
 * <p>
 * Schema {@code schemaVersion} 1:
 * <ul>
 *   <li>{@code clanName}, {@code members[]} — {@code name}, {@code standardizedName}, {@code rank}
 *       (display rank: custom clan title when set, otherwise a readable Jagex rank name),
 *       {@code rankLevel} (Jagex rank index), {@code rankTitle} (same as {@code rank} when the clan assigns a title),
 *       {@code joinDate} (ISO-8601 date when known)</li>
 *   <li>{@code leftMembers[]} — optional; members present on the prior snapshot but missing now:
 *       {@code name}, {@code standardizedName}, {@code leftAtEpochMs}, plus {@code lastRank},
 *       {@code lastRankLevel} (when present), {@code lastRankTitle}, {@code lastJoinDate} from the last seen roster row</li>
 * </ul>
 */
@Singleton
public class ClanRosterSitePayloadBuilder
{
	private static final String CONFIG_GROUP = "terpinheimer";

	private final Gson gson;
	private final TerpinheimerConfig config;
	private final ConfigManager configManager;
	private final ClanRosterSnapshotTracker rosterSnapshotTracker;

	@Inject
	ClanRosterSitePayloadBuilder(
		Gson gson,
		TerpinheimerConfig config,
		ConfigManager configManager,
		ClanRosterSnapshotTracker rosterSnapshotTracker)
	{
		this.gson = gson;
		this.config = config;
		this.configManager = configManager;
		this.rosterSnapshotTracker = rosterSnapshotTracker;
	}

	/**
	 * @return JSON or {@code null} when not in a clan or settings are unavailable
	 */
	public String buildJson(Client client)
	{
		ClanSettings settings = client.getClanSettings();
		if (settings == null)
		{
			return null;
		}
		String clanName = settings.getName();
		if (clanName == null)
		{
			clanName = "";
		}

		long nowMs = System.currentTimeMillis();
		JsonObject root = new JsonObject();
		root.addProperty("schemaVersion", 1);
		addSyncTokenFields(root);
		root.addProperty("syncedAtEpochMs", nowMs);
		String rl = RuneLiteProperties.getVersion();
		root.addProperty("runeliteVersion", rl != null ? rl : "unknown");
		root.addProperty("pluginVersion", "2.0.1");
		root.addProperty("clanName", clanName);

		if (client.getLocalPlayer() != null)
		{
			String uploader = Text.removeTags(client.getLocalPlayer().getName());
			if (uploader != null)
			{
				uploader = uploader.trim().replace('\u00A0', ' ');
				root.addProperty("syncedByDisplayName", uploader);
			}
		}

		JsonArray members = new JsonArray();
		List<?> list = settings.getMembers();
		if (list != null)
		{
			for (Object o : list)
			{
				if (!(o instanceof ClanMember))
				{
					continue;
				}
				ClanMember m = (ClanMember) o;
				JsonObject row = memberRow(settings, m);
				if (row != null)
				{
					members.add(row);
				}
			}
		}
		root.add("members", members);

		boolean stillInClan = client.getLocalPlayer() != null && client.getLocalPlayer().isClanMember();
		JsonArray leftMembers = rosterSnapshotTracker.takeLeftMemberRows(clanName, members, stillInClan, nowMs);
		if (leftMembers.size() > 0)
		{
			root.add("leftMembers", leftMembers);
		}

		return gson.toJson(root);
	}

	private JsonObject memberRow(ClanSettings settings, ClanMember m)
	{
		String name = m.getName();
		if (name == null)
		{
			return null;
		}
		name = Text.removeTags(name).trim().replace('\u00A0', ' ');
		if (name.isEmpty())
		{
			return null;
		}
		JsonObject row = new JsonObject();
		row.addProperty("name", name);
		String std = Text.standardize(name);
		row.addProperty("standardizedName", std);

		ClanRank rank = m.getRank();
		if (rank != null)
		{
			row.addProperty("rankLevel", rank.getRank());
			String rankDisplay = ClanMemberRankDisplay.forMember(settings, m);
			if (rankDisplay != null)
			{
				ClanTitle title = settings.titleForRank(rank);
				if (title != null && title.getName() != null && !title.getName().isEmpty())
				{
					row.addProperty("rankTitle", rankDisplay);
				}
				row.addProperty("rank", rankDisplay);
			}
		}

		if (m.getJoinDate() != null)
		{
			row.addProperty("joinDate", m.getJoinDate().toString());
		}

		return row;
	}

	private void addSyncTokenFields(JsonObject root)
	{
		String token = resolveClanSecret();
		if (token.isEmpty())
		{
			return;
		}
		root.addProperty("syncToken", token);
		root.addProperty("sync_token", token);
	}

	private String resolveClanSecret()
	{
		String st = configManager.getConfiguration(CONFIG_GROUP, "clanSecret");
		if (st == null || st.trim().isEmpty())
		{
			st = config.clanSecret();
		}
		if (st == null || st.trim().isEmpty())
		{
			for (String legacyKey : new String[] {"clogSyncApiSecret", "clanRosterSyncApiSecret", "liveMapApiKey"})
			{
				String legacy = configManager.getConfiguration(CONFIG_GROUP, legacyKey);
				if (legacy != null && !legacy.trim().isEmpty())
				{
					st = legacy;
					break;
				}
			}
		}
		if (st == null)
		{
			return "";
		}
		String token = st.trim();
		if (token.regionMatches(true, 0, "Bearer ", 0, 7))
		{
			token = token.substring(7).trim();
		}
		return token;
	}
}

