	private String fetchJson(String httpsUrl) throws IOException
	{
		String rl = RuneLiteProperties.getVersion();
		String ua = "Terpinheimer/2.0.0 RuneLite/" + (rl != null ? rl : "unknown");
		Request req = new Request.Builder()
			.url(httpsUrl)
			.header("User-Agent", ua)
			.header("Accept", "application/json")
			.get()
			.build();
		try (Response res = http.newCall(req).execute())
		{
			ResponseBody b = res.body();
			String body = b != null ? b.string() : "";
			if (!res.isSuccessful())
			{
				throw new IOException("HTTP " + res.code());
			}
			return body;
		}
	}

	private TerpinheimerRemoteConfigDto parse(String json)
	{
		JsonObject root = gson.fromJson(json, JsonObject.class);
		if (root == null)
		{
			return new TerpinheimerRemoteConfigDto();
		}
		TerpinheimerRemoteConfigDto dto = new TerpinheimerRemoteConfigDto();
		if (root.has("announcements") && root.get("announcements").isJsonObject())
		{
			dto.announcements = gson.fromJson(root.get("announcements"), TerpinheimerRemoteConfigDto.Announcements.class);
		}
		applyPermissions(root, dto);
		return dto;
	}

	private static void applyPermissions(JsonObject root, TerpinheimerRemoteConfigDto dto)
	{
		if (dto.permissions == null)
		{
			dto.permissions = new TerpinheimerRemoteConfigDto.Permissions();
		}

		setIfPresent(root, "clanRosterPostRankTitles", v -> dto.permissions.clanRosterPostRankTitles = v);
		setIfPresent(root, "clanEventTrackerRankTitles", v -> dto.permissions.clanEventTrackerRankTitles = v);

		if (root.has("permissions") && root.get("permissions").isJsonObject())
		{
			JsonObject perms = root.getAsJsonObject("permissions");
			setIfPresent(perms, "clanRosterPostRankTitles", v -> dto.permissions.clanRosterPostRankTitles = v);
			setIfPresent(perms, "clanEventTrackerRankTitles", v -> dto.permissions.clanEventTrackerRankTitles = v);
			applyPermissionArray(perms, "clanRosterPostRankTitles", titles -> dto.permissions.clanRosterPostRankTitles = titles);
			applyPermissionArray(perms, "clanEventTrackerRankTitles", titles -> dto.permissions.clanEventTrackerRankTitles = titles);
		}

		applyPermissionArray(root, "clanRosterPostRankTitles", titles -> dto.permissions.clanRosterPostRankTitles = titles);
		applyPermissionArray(root, "clanEventTrackerRankTitles", titles -> dto.permissions.clanEventTrackerRankTitles = titles);
	}

	private String permissionsField(String key)
	{
		TerpinheimerRemoteConfigDto.Permissions p = active.permissions;
		if (p == null)
		{
			return null;
		}
		switch (key)
		{
			case "clanRosterPostRankTitles":
				return p.clanRosterPostRankTitles;
			case "clanEventTrackerRankTitles":
				return p.clanEventTrackerRankTitles;
			default:
				return null;
		}
	}

	private static void applyPermissionArray(JsonObject root, String key, java.util.function.Consumer<String> setter)
	{
		if (!root.has(key) || root.get(key).isJsonNull())
		{
			return;
		}
		JsonElement el = root.get(key);
		if (!el.isJsonArray())
		{
			return;
		}
		List<String> titles = RankTitlePermissionList.parseJsonElement(el);
		if (!titles.isEmpty())
		{
			setter.accept(String.join(",", titles));
		}
	}

	private static void setIfPresent(JsonObject root, String key, java.util.function.Consumer<String> setter)
	{
		if (!root.has(key) || root.get(key).isJsonNull())
		{
			return;
		}
		JsonElement el = root.get(key);
		if (el.isJsonPrimitive())
		{
			String v = el.getAsString();
			if (v != null)
			{
				setter.accept(v.trim());
			}
		}
	}
}

package com.terpinheimer.site;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Builds {@code itemIds} for clog sync from bundled {@code /collection-varbit-to-item-id.json}
 * (varbit id string → OSRS item id). Generated on the website via
 * {@code npm run clog:varbit-pipeline} — no Java reflection.
 */
@Singleton
public final class CollectionLogItemIdsSupport
{
	private static final Logger log = LoggerFactory.getLogger(CollectionLogItemIdsSupport.class);
	private static final String VARBIT_TO_ITEM_RESOURCE = "/collection-varbit-to-item-id.json";

	private final Gson gson;
	private volatile Map<String, Integer> varbitKeyToItemId;

	@Inject
	CollectionLogItemIdsSupport(Gson gson)
	{
		this.gson = gson;
		this.varbitKeyToItemId = null;
	}

	/** For each non-zero varbit key in {@code varbits}, add mapped item id when present in the resource. */
	void addItemIdsFromVarbitResource(JsonObject varbits, Set<Integer> out)
	{
		if (varbits == null || varbits.size() == 0 || out == null)
		{
			return;
		}
		Map<String, Integer> map = varbitToItemMap();
		if (map.isEmpty())
		{
			return;
		}
		for (Map.Entry<String, JsonElement> e : varbits.entrySet())
		{
			JsonElement el = e.getValue();
			if (el == null || !el.isJsonPrimitive() || !el.getAsJsonPrimitive().isNumber())
			{
				continue;
			}
			if (el.getAsInt() == 0)
			{
				continue;
			}
			Integer item = map.get(e.getKey());
			if (item != null && item > 0)
			{
				out.add(item);
			}
		}
	}

	private Map<String, Integer> varbitToItemMap()
	{
		Map<String, Integer> m = varbitKeyToItemId;
		if (m != null)
		{
			return m;
		}
		synchronized (this)
		{
			if (varbitKeyToItemId != null)
			{
				return varbitKeyToItemId;
			}
			varbitKeyToItemId = readVarbitToItemResource();
			return varbitKeyToItemId;
		}
	}

	private Map<String, Integer> readVarbitToItemResource()
	{
		try (InputStream in = CollectionLogItemIdsSupport.class.getResourceAsStream(VARBIT_TO_ITEM_RESOURCE))
		{
			if (in == null)
			{
				log.warn("Terpinheimer: missing {} — run clog:sync-varbit-to-plugin on the website repo", VARBIT_TO_ITEM_RESOURCE);
				return Map.of();
			}
			JsonObject o = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), JsonObject.class);
			if (o == null)
			{
				return Map.of();
			}
			HashMap<String, Integer> map = new HashMap<>();
			for (Map.Entry<String, JsonElement> e : o.entrySet())
			{
				if ("version".equals(e.getKey()) || "description".equals(e.getKey()))
				{
					continue;
				}
				if (!e.getValue().isJsonPrimitive() || !e.getValue().getAsJsonPrimitive().isNumber())
				{
					continue;
				}
				int item = e.getValue().getAsInt();
				if (item > 0)
				{
					map.put(e.getKey(), item);
				}
			}
			log.debug("Terpinheimer: loaded {} varbit→item mappings from {}", map.size(), VARBIT_TO_ITEM_RESOURCE);
			return map;
		}
		catch (Exception e)
		{
			log.warn("Terpinheimer: could not load {}: {}", VARBIT_TO_ITEM_RESOURCE, e.toString());
			return Map.of();
		}
	}
}

package com.terpinheimer.site;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Tracks the last roster POST snapshot per clan name so the next payload can list members who
 * disappeared (leave date = {@code leftAtEpochMs} on the server when it merges this array).
 */
@Singleton
public class ClanRosterSnapshotTracker
{
	/** Jagex clan name from {@code ClanSettings#getName()} for the last stored snapshot. */
	private String snapshotClanName = "";
	private final Map<String, JsonObject> lastMembersByStd = new HashMap<>();

	@Inject
	ClanRosterSnapshotTracker()
	{
	}

	public void reset()
	{
		snapshotClanName = "";
		lastMembersByStd.clear();
	}

	/**
	 * Compares {@code currentMemberRows} to the last snapshot, updates the stored snapshot, and
	 * returns rows for members who are no longer present.
	 *
	 * @param playerStillInClan when the current member list is empty but this is true, transient
	 *                          load is assumed and no mass-leave rows are emitted
	 */
	public JsonArray takeLeftMemberRows(String clanName, JsonArray currentMemberRows, boolean playerStillInClan, long nowMs)
	{
		if (clanName == null)
		{
			clanName = "";
		}
		if (!clanName.equals(snapshotClanName))
		{
			snapshotClanName = clanName;
			lastMembersByStd.clear();
		}

		Set<String> currentStd = new HashSet<>();
		Map<String, JsonObject> currentCopy = new HashMap<>();
		for (int i = 0; i < currentMemberRows.size(); i++)
		{
			JsonObject row = currentMemberRows.get(i).getAsJsonObject();
			if (!row.has("standardizedName"))
			{
				continue;
			}
			String std = row.get("standardizedName").getAsString();
			currentStd.add(std);
			currentCopy.put(std, copyMemberSnapshot(row));
		}

		JsonArray left = new JsonArray();
		if (!lastMembersByStd.isEmpty())
		{
			if (!currentStd.isEmpty())
			{
				for (Map.Entry<String, JsonObject> e : lastMembersByStd.entrySet())
				{
					if (!currentStd.contains(e.getKey()))
					{
						left.add(buildLeftRow(e.getValue(), nowMs));
					}
				}
			}
			else if (!playerStillInClan)
			{
				for (JsonObject prev : lastMembersByStd.values())
				{
					left.add(buildLeftRow(prev, nowMs));
				}
			}
		}

		lastMembersByStd.clear();
		lastMembersByStd.putAll(currentCopy);
		return left;
	}

	private static JsonObject copyMemberSnapshot(JsonObject row)
	{
		JsonObject c = new JsonObject();
		copyIfPresent(row, c, "name");
		copyIfPresent(row, c, "standardizedName");
		copyIfPresent(row, c, "rank");
		copyIfPresent(row, c, "rankLevel");
		copyIfPresent(row, c, "rankTitle");
		copyIfPresent(row, c, "joinDate");
		return c;
	}

	private static void copyIfPresent(JsonObject from, JsonObject to, String key)
	{
		if (from.has(key))
		{
			to.add(key, from.get(key));
		}
	}

	private static JsonObject buildLeftRow(JsonObject lastMember, long nowMs)
	{
		JsonObject o = new JsonObject();
		if (lastMember.has("name"))
		{
			o.add("name", lastMember.get("name"));
		}
		if (lastMember.has("standardizedName"))
		{
			o.add("standardizedName", lastMember.get("standardizedName"));
		}
		o.addProperty("leftAtEpochMs", nowMs);
		if (lastMember.has("rank"))
		{
			o.add("lastRank", lastMember.get("rank"));
		}
		if (lastMember.has("rankLevel"))
		{
			o.add("lastRankLevel", lastMember.get("rankLevel"));
		}
		if (lastMember.has("rankTitle"))
		{
			o.add("lastRankTitle", lastMember.get("rankTitle"));
		}
		if (lastMember.has("joinDate"))
		{
			o.add("lastJoinDate", lastMember.get("joinDate"));
		}
		return o;
	}
}

package com.terpinheimer.site;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.VarPlayer;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Quest, achievement diary, and music progress for collection-log site sync.
 * Nested under {@code accountProgress} so v2 clog item/varbit saves stay compatible; {@code musicVarps}
 * is also copied to the root for hosts that only read bitfields there.
 */
@Singleton
public final class ClogAccountProgressSnapshot
{
	private static final Logger log = LoggerFactory.getLogger(ClogAccountProgressSnapshot.class);

	private static final int[] MUSIC_VAR_PLAYER_IDS = {
		VarPlayerID.MUSICMULTI_1,
		VarPlayerID.MUSICMULTI_2,
		VarPlayerID.MUSICMULTI_3,
		VarPlayerID.MUSICMULTI_4,
		VarPlayerID.MUSICMULTI_5,
		VarPlayerID.MUSICMULTI_6,
		VarPlayerID.MUSICMULTI_7,
		VarPlayerID.MUSICMULTI_8,
		VarPlayerID.MUSICMULTI_9,
		VarPlayerID.MUSICMULTI_10,
		VarPlayerID.MUSICMULTI_11,
		VarPlayerID.MUSICMULTI_12,
		VarPlayerID.MUSICMULTI_13,
		VarPlayerID.MUSICMULTI_14,
		VarPlayerID.MUSICMULTI_15,
		VarPlayerID.MUSICMULTI_16,
		VarPlayerID.MUSICMULTI_17,
		VarPlayerID.MUSICMULTI_18,
		VarPlayerID.MUSICMULTI_19,
		VarPlayerID.MUSICMULTI_20,
		VarPlayerID.MUSICMULTI_21,
		VarPlayerID.MUSICMULTI_22,
		VarPlayerID.MUSICMULTI_23,
		VarPlayerID.MUSICMULTI_24,
		VarPlayerID.MUSICMULTI_25,
		VarPlayerID.MUSICMULTI_26,
		VarPlayerID.MUSICMULTI_27,
	};

	@Inject
	ClogAccountProgressSnapshot()
	{
	}

	void writeTo(JsonObject root, Client client)
	{
		if (root == null || client == null)
		{
			return;
		}
		JsonObject progress = new JsonObject();
		progress.addProperty("questPoints", client.getVarpValue(VarPlayer.QUEST_POINTS));
		writeQuests(progress, client);
		writeAchievementDiaryTiers(progress, client);
		writeMusic(progress, client);
		root.add("accountProgress", progress);
		// Site fallback: decode unlocks from bitfields when row lists are not stored.
		root.add("musicVarps", progress.getAsJsonObject("musicVarps").deepCopy());
		root.addProperty("musicUnlockedCount", progress.get("musicUnlockedCount").getAsInt());
	}

	private static void writeQuests(JsonObject target, Client client)
	{
		JsonObject quests = new JsonObject();
		JsonArray finished = new JsonArray();
		int finishedCount = 0;
		for (Quest quest : Quest.values())
		{
			QuestState state = quest.getState(client);
			int code = questStateCode(state);
			quests.addProperty(Integer.toString(quest.getId()), code);
			if (state == QuestState.FINISHED)
			{
				finished.add(quest.getId());
				finishedCount++;
			}
		}
		target.add("quests", quests);
		target.add("questsFinished", finished);
		target.addProperty("questsFinishedCount", finishedCount);
	}

	/** RuneProfile-aligned: 0 = not started, 1 = in progress, 2 = finished. */
	private static int questStateCode(QuestState state)
	{
		if (state == QuestState.FINISHED)
		{
			return 2;
		}
		if (state == QuestState.IN_PROGRESS)
		{
			return 1;
		}
		return 0;
	}

	private static void writeAchievementDiaryTiers(JsonObject target, Client client)
	{
		JsonArray tiers = new JsonArray();
		for (DiaryArea area : DiaryArea.values())
		{
			int[] completedCounts = area.getTiersCompletedCount(client);
			for (int tierIndex = 0; tierIndex < completedCounts.length; tierIndex++)
			{
				JsonObject tier = new JsonObject();
				tier.addProperty("areaId", area.getId());
				tier.addProperty("tierIndex", tierIndex);
				int count = completedCounts[tierIndex];
				if (count < 0)
				{
					count = 0;
				}
				tier.addProperty("completedCount", count);
				tiers.add(tier);
			}
		}
		target.add("achievementDiaryTiers", tiers);
	}

	private static void writeMusic(JsonObject target, Client client)
	{
		JsonObject musicVarps = new JsonObject();
		int varpBitCount = 0;
		for (int i = 0; i < MUSIC_VAR_PLAYER_IDS.length; i++)
		{
			int value = client.getVarpValue(MUSIC_VAR_PLAYER_IDS[i]);
			musicVarps.addProperty("musicMulti" + (i + 1), value);
			varpBitCount += Integer.bitCount(value);
		}
		target.add("musicVarps", musicVarps);
		target.addProperty("musicUnlockedCount", varpBitCount);

		JsonArray unlocked = new JsonArray();
		try
		{
			List<Integer> rows = client.getDBTableRows(DBTableID.Music.ID);
			if (rows != null)
			{
				for (Integer row : rows)
				{
					if (row == null || row <= 0)
					{
						continue;
					}
					if (isMusicRowUnlocked(client, row))
					{
						unlocked.add(row);
					}
				}
			}
		}
		catch (Exception e)
		{
			log.debug("Terpinheimer: music row scan skipped: {}", e.toString());
		}
		if (unlocked.size() > 0)
		{
			target.add("musicUnlocked", unlocked);
		}
	}

	private static boolean isMusicRowUnlocked(Client client, int rowId)
	{
		if (isAutomaticMusicUnlock(client, rowId))
		{
			return true;
		}
		Object[] variable = client.getDBTableField(rowId, DBTableID.Music.COL_VARIABLE, 0);
		if (variable == null || variable.length == 0)
		{
			return false;
		}
		if (variable.length >= 2 && variable[0] instanceof Number && variable[1] instanceof Number)
		{
			int first = ((Number) variable[0]).intValue();
			int bit = ((Number) variable[1]).intValue();
			int varpId = resolveMusicVarpId(first);
			if (varpId > 0 && bit >= 0 && bit < 32)
			{
				return (client.getVarpValue(varpId) & (1 << bit)) != 0;
			}
		}
		if (variable[0] instanceof Number)
		{
			int packed = ((Number) variable[0]).intValue();
			if (packed <= 0)
			{
				return false;
			}
			int varbitId = packed >> 16;
			int expected = packed & 0xFFFF;
			if (varbitId > 0)
			{
				return client.getVarbitValue(varbitId) == expected;
			}
		}
		return false;
	}

	private static int resolveMusicVarpId(int musicMultiIndexOrVarpId)
	{
		if (musicMultiIndexOrVarpId >= 1 && musicMultiIndexOrVarpId <= MUSIC_VAR_PLAYER_IDS.length)
		{
			return MUSIC_VAR_PLAYER_IDS[musicMultiIndexOrVarpId - 1];
		}
		for (int varpId : MUSIC_VAR_PLAYER_IDS)
		{
			if (varpId == musicMultiIndexOrVarpId)
			{
				return varpId;
			}
		}
		return -1;
	}

	private static boolean isAutomaticMusicUnlock(Client client, int rowId)
	{
		Object[] auto = client.getDBTableField(rowId, DBTableID.Music.COL_AUTOMATIC_UNLOCK, 0);
		return auto != null && auto.length > 0 && auto[0] instanceof Number && ((Number) auto[0]).intValue() != 0;
	}

	private enum DiaryArea
	{
		KARAMJA(0),
		ARDOUGNE(1),
		FALADOR(2),
		FREMENNIK(3),
		KANDARIN(4),
		DESERT(5),
		LUMBRIDGE(6),
		MORYTANIA(7),
		VARROCK(8),
		WILDERNESS(9),
		WESTERN_PROVINCES(10),
		KOUREND(11);

		private final int id;

		DiaryArea(int id)
		{
			this.id = id;
		}

		int getId()
		{
			return id;
		}

		int[] getTiersCompletedCount(Client client)
		{
			client.runScript(2200, id);
			int[] stack = client.getIntStack();
			if (stack == null || stack.length < 10)
			{
				return new int[] {0, 0, 0, 0};
			}
			return new int[] {stack[0], stack[3], stack[6], stack[9]};
		}
	}
}

