 * Incremental collection log unlocks (RuneProfile-style): game chat when a new item is logged.
 */
@Singleton
public final class CollectionLogUnlockCapture
{
	private static final Logger log = LoggerFactory.getLogger(CollectionLogUnlockCapture.class);
	private static final Pattern NEW_ITEM =
		Pattern.compile("(?i)new item added to your collection log:\\s*(.+)");

	private final Client client;
	private final ItemManager itemManager;
	private final CollectionLogItemStore collectionLogItemStore;
	private final RuneProfilePresence runeProfilePresence;

	@Inject
	CollectionLogUnlockCapture(
		Client client,
		ItemManager itemManager,
		CollectionLogItemStore collectionLogItemStore,
		RuneProfilePresence runeProfilePresence)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.collectionLogItemStore = collectionLogItemStore;
		this.runeProfilePresence = runeProfilePresence;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGGED_IN)
		{
			collectionLogItemStore.reloadForCurrentAccount();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (runeProfilePresence.isEnabled())
		{
			return;
		}
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String plain = Text.removeTags(event.getMessage());
		if (plain == null || plain.isEmpty())
		{
			return;
		}
		Matcher m = NEW_ITEM.matcher(plain);
		if (!m.find())
		{
			return;
		}
		String itemName = m.group(1).trim();
		if (itemName.isEmpty() || shouldIgnoreAmbiguousName(itemName))
		{
			return;
		}
		int itemId = resolveItemId(itemName);
		if (itemId <= 0)
		{
			log.debug("Terpinheimer: could not resolve clog unlock item name: {}", itemName);
			return;
		}
		collectionLogItemStore.storeItem(itemId, 1);
		collectionLogItemStore.persistNow();
	}

	private int resolveItemId(String itemName)
	{
		try
		{
			java.util.List<ItemPrice> hits = itemManager.search(itemName);
			if (hits == null || hits.isEmpty())
			{
				return -1;
			}
			return hits.get(0).getId();
		}
		catch (Exception e)
		{
			return -1;
		}
	}

	private static boolean shouldIgnoreAmbiguousName(String itemName)
	{
		String low = itemName.toLowerCase(Locale.ROOT);
		return low.contains(" graceful ") || low.startsWith("graceful ")
			|| low.endsWith(" graceful") || low.equals("graceful");
	}
}

package com.terpinheimer.site;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * RuneProfile-style collection log storage: {@code Map<itemId, quantity>} persisted per Jagex account hash.
 * In-memory updates during script 4100 must not write config on the client thread (causes log UI freezes).
 */
@Singleton
public final class CollectionLogItemStore
{
	private static final Logger log = LoggerFactory.getLogger(CollectionLogItemStore.class);
	private static final String CONFIG_GROUP = "terpinheimer";
	private static final String CONFIG_KEY_PREFIX = "clogItems.";
	private static final Type MAP_TYPE = new TypeToken<Map<String, Integer>>() {}.getType();

	private final Client client;
	private final ConfigManager configManager;
	private final Gson gson;
	private final Map<Integer, Integer> items = new HashMap<>();
	private volatile boolean dirty;

	@Inject
	CollectionLogItemStore(Client client, ConfigManager configManager, Gson gson)
	{
		this.client = client;
		this.configManager = configManager;
		this.gson = gson;
	}

	public void reloadForCurrentAccount()
	{
		long hash = client.getAccountHash();
		synchronized (items)
		{
			items.clear();
			dirty = false;
			if (hash == 0L)
			{
				return;
			}
			String raw = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_PREFIX + hash);
			if (raw == null || raw.isEmpty())
			{
				return;
			}
			Map<String, Integer> parsed = gson.fromJson(raw, MAP_TYPE);
			if (parsed == null)
			{
				return;
			}
			for (Map.Entry<String, Integer> e : parsed.entrySet())
			{
				try
				{
					int id = Integer.parseInt(e.getKey());
					int qty = e.getValue() != null ? e.getValue() : 0;
					if (id > 0 && qty > 0)
					{
						items.put(id, Math.min(65535, qty));
					}
				}
				catch (NumberFormatException ignored)
				{
					// skip
				}
			}
		}
		log.debug("Terpinheimer: loaded {} collection log item(s) from disk", items.size());
	}

	/**
	 * Updates the in-memory map only. Call {@link #persistNow()} after the log closes or before site sync.
	 */
	public void storeItem(int itemId, int quantity)
	{
		if (itemId <= 0 || quantity <= 0)
		{
			return;
		}
		int qty = Math.min(65535, quantity);
		synchronized (items)
		{
			Integer prev = items.get(itemId);
			int merged = prev == null ? qty : Math.max(prev, qty);
			if (prev == null || merged != prev)
			{
				items.put(itemId, merged);
				dirty = true;
			}
		}
	}

	/** Writes the in-memory map to RuneLite config (client thread). */
	public void persistNow()
	{
		if (!dirty)
		{
			return;
		}
		persistForCurrentAccount();
		dirty = false;
	}

	public int size()
	{
		synchronized (items)
		{
			return items.size();
		}
	}

	public void writeItemsJson(JsonObject root)
	{
		if (root == null)
		{
			return;
		}
		JsonObject map = new JsonObject();
		synchronized (items)
		{
			for (Map.Entry<Integer, Integer> e : items.entrySet())
			{
				map.addProperty(Integer.toString(e.getKey()), e.getValue());
			}
		}
		if (map.size() > 0)
		{
			root.add("items", map);
		}
	}

	private void persistForCurrentAccount()
	{
		long hash = client.getAccountHash();
		if (hash == 0L)
		{
			return;
		}
		Map<String, Integer> out = new HashMap<>();
		synchronized (items)
		{
			for (Map.Entry<Integer, Integer> e : items.entrySet())
			{
				out.put(Integer.toString(e.getKey()), e.getValue());
			}
		}
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_PREFIX + hash, gson.toJson(out));
	}
}

package com.terpinheimer.site;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/**
 * Detects whether the RuneProfile hub plugin is enabled. Its
 * {@code CollectionLogWidgetSubscriber} calls {@code runScript} from script callbacks and
 * conflicts with other collection-log tooling.
 */
@Singleton
public final class RuneProfilePresence
{
	private final PluginManager pluginManager;

	@Inject
	RuneProfilePresence(PluginManager pluginManager)
	{
		this.pluginManager = pluginManager;
	}

	public boolean isEnabled()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin == null)
			{
				continue;
			}
			String name = plugin.getClass().getName();
			if (name.startsWith("com.runeprofile.") && pluginManager.isPluginEnabled(plugin))
			{
				return true;
			}
		}
		return false;
	}
}

package com.terpinheimer.site;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Reads collection-log varbits via {@link Client#getVarbitValue(int)} using a bundled id list
 * ({@code /collection-varbit-ids.json}) — no runtime reflection on RuneLite gameval classes.
 */
@Singleton
public final class CollectionLogVarbitSnapshot
{
	private static final Logger log = LoggerFactory.getLogger(CollectionLogVarbitSnapshot.class);
	private static final String VARBIT_IDS_RESOURCE = "/collection-varbit-ids.json";
	private static final Type INT_LIST_TYPE = new TypeToken<List<Integer>>() {}.getType();

	private final Gson gson;
	private volatile int[] varbitIds;

	@Inject
	CollectionLogVarbitSnapshot(Gson gson)
	{
		this.gson = gson;
	}

	/** Fills {@code out} with non-zero varbit values (keys = varbit id strings). */
	void snapshot(Client client, JsonObject out)
	{
		if (client == null || out == null)
		{
			return;
		}
		for (int varbitId : varbitIds())
		{
			int value = client.getVarbitValue(varbitId);
			if (value != 0)
			{
				out.addProperty(Integer.toString(varbitId), value);
			}
		}
	}

	private int[] varbitIds()
	{
		int[] cached = varbitIds;
		if (cached != null)
		{
			return cached;
		}
		synchronized (this)
		{
			if (varbitIds != null)
			{
				return varbitIds;
			}
			varbitIds = loadVarbitIds();
			return varbitIds;
		}
	}

	private int[] loadVarbitIds()
	{
		try (InputStream in = CollectionLogVarbitSnapshot.class.getResourceAsStream(VARBIT_IDS_RESOURCE))
		{
			if (in == null)
			{
				log.warn("Terpinheimer: missing {}", VARBIT_IDS_RESOURCE);
				return new int[0];
			}
			List<Integer> list = gson.fromJson(new InputStreamReader(in, StandardCharsets.UTF_8), INT_LIST_TYPE);
			if (list == null || list.isEmpty())
			{
				return new int[0];
			}
			int[] out = new int[list.size()];
			int n = 0;
			for (Integer id : list)
			{
				if (id != null && id > 0)
				{
					out[n++] = id;
				}
			}
			if (n < out.length)
			{
				int[] trimmed = new int[n];
				System.arraycopy(out, 0, trimmed, 0, n);
				out = trimmed;
			}
			log.debug("Terpinheimer: loaded {} collection varbit ids from {}", out.length, VARBIT_IDS_RESOURCE);
			return out;
		}
		catch (Exception e)
		{
			log.warn("Terpinheimer: could not load {}: {}", VARBIT_IDS_RESOURCE, e.toString());
			return new int[0];
		}
	}
}

package com.terpinheimer.site;

import java.util.Locale;
import java.util.regex.Pattern;

/** Shared filters so opening the collection log UI does not match broad "collection log" chat. */
public final class CollectionLogChatFilters
{
	private static final Pattern ITEM_ADDED =
		Pattern.compile("(?i)added (?:an? |the )?(.+?) to your collection");

	private CollectionLogChatFilters()
	{
	}

	public static boolean isUnlockNotification(String plain)
	{
		if (plain == null || plain.isEmpty())
		{
			return false;
		}
		String low = plain.toLowerCase(Locale.ROOT);
		return low.contains("new item added to your collection log")
			|| low.contains("added to your collection log")
			|| ITEM_ADDED.matcher(plain).find();
	}
}

