		if (collectionLogUiState.isCollectionLogOpen(client))
		{
			clogXpSyncDebounce = scheduledExecutor.schedule(
				() -> clientThread.invokeLater(this::scheduleClogSiteSyncFromXpWhenSafe),
				CLOG_XP_SYNC_RETRY_SECONDS,
				TimeUnit.SECONDS);
			return;
