	private String statusLabel(WomLeaderboardModels.CompetitionSnapshot s)
	{
		if (!s.isAvailable())
		{
			if (s.getError() != null && !s.getError().isEmpty())
			{
				return "Error";
			}
			return "No data";
		}
		switch (s.getPhase())
		{
			case ACTIVE:
				return "Active";
			case UPCOMING:
				return "Upcoming";
			case FINISHED:
				return "Finished";
			default:
				return "—";
		}
	}

