package com.terpinheimer.wom;

import com.terpinheimer.TerpinheimerLinks;
import java.io.IOException;
import java.util.Locale;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * Triggers a Wise Old Man hiscores update for the logged-in player (POST /v2/players/:username),
 * matching the hub plugin / XP Updater behavior on logout.
 */
@Singleton
public class WomPlayerUpdateService
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String API = TerpinheimerLinks.WOM_API_BASE;

	private final OkHttpClient http;

	@Inject
	public WomPlayerUpdateService(OkHttpClient http)
	{
		this.http = http;
	}

	/**
	 * Asks WOM to (re)import the player from the hiscores. Username should be the in-game
	 * name (spaces are normalized to underscores; casing is lowercased for the URL).
	 */
	public void requestUpdate(String displayName) throws IOException
	{
		if (displayName == null || displayName.isBlank())
		{
			return;
		}
		String slug = displayName.trim().replace('\u00A0', ' ').replace(' ', '_').toLowerCase(Locale.ENGLISH);
		HttpUrl url = HttpUrl.parse(API).newBuilder()
			.addPathSegment("players")
			.addPathSegment(slug)
			.build();
		Request req = new Request.Builder()
			.url(url)
			.post(RequestBody.create(JSON, ""))
			.header("Accept", "application/json")
			.build();
		try (Response res = http.newCall(req).execute())
		{
			// 200 / 201 = success; 400 / 429 etc. — caller may log; avoid spamming throws
			if (!res.isSuccessful() && res.body() != null)
			{
				res.body().close();
			}
		}
	}
}

package com.terpinheimer.wom;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

/**
 * Immutable snapshot for UI after parsing Wise Old Man competition JSON.
 */
public final class WomLeaderboardModels
{
	private WomLeaderboardModels()
	{
	}

	public enum EventPhase
	{
		UPCOMING,
		ACTIVE,
		FINISHED,
		UNKNOWN
	}

	public static final class LeaderRow
	{
		private final int rank;
		private final String playerName;
		private final long gained;
		private final String tooltip;

		public LeaderRow(int rank, String playerName, long gained, String tooltip)
		{
			this.rank = rank;
			this.playerName = playerName;
			this.gained = gained;
			this.tooltip = tooltip;
		}

		public int getRank()
		{
			return rank;
		}

		public String getPlayerName()
		{
			return playerName;
		}

		public long getGained()
		{
			return gained;
		}

		public String getTooltip()
		{
			return tooltip;
		}
	}

	public static final class CompetitionSnapshot
	{
		private final boolean available;
		private final String error;
		private final long competitionId;
		private final String title;
		private final String metric;
		private final Instant startsAt;
		private final Instant endsAt;
		private final EventPhase phase;
		private final List<LeaderRow> top10;
		private final LeaderRow winner;
		private final long lastUpdatedEpochMs;
		private final String countdownHint;

		private CompetitionSnapshot(boolean available, String error, long competitionId, String title, String metric,
			Instant startsAt, Instant endsAt, EventPhase phase, List<LeaderRow> top10, LeaderRow winner,
			long lastUpdatedEpochMs, String countdownHint)
		{
			this.available = available;
			this.error = error;
			this.competitionId = competitionId;
			this.title = title;
			this.metric = metric;
			this.startsAt = startsAt;
			this.endsAt = endsAt;
			this.phase = phase;
			this.top10 = top10;
			this.winner = winner;
			this.lastUpdatedEpochMs = lastUpdatedEpochMs;
			this.countdownHint = countdownHint;
		}

		public static CompetitionSnapshot error(String message)
		{
			return new CompetitionSnapshot(false, message, 0L, "", "", null, null, EventPhase.UNKNOWN,
				Collections.emptyList(), null, 0L, "");
		}

		public static CompetitionSnapshot empty(String hint)
		{
			return new CompetitionSnapshot(false, "", 0L, "", "", null, null, EventPhase.UNKNOWN,
				Collections.emptyList(), null, 0L, hint);
		}

		public static CompetitionSnapshot ok(long competitionId, String title, String metric, Instant startsAt, Instant endsAt,
			EventPhase phase, List<LeaderRow> top10, LeaderRow winner, long lastUpdatedEpochMs, String countdownHint)
		{
			return new CompetitionSnapshot(true, "", competitionId, title, metric, startsAt, endsAt, phase, top10, winner,
				lastUpdatedEpochMs, countdownHint);
		}

		public boolean isAvailable()
		{
			return available;
		}

		public String getError()
		{
			return error;
		}

		public long getCompetitionId()
		{
			return competitionId;
		}

		public String getTitle()
		{
			return title;
		}

		public String getMetric()
		{
			return metric;
		}

		public Instant getStartsAt()
		{
			return startsAt;
		}

		public Instant getEndsAt()
		{
			return endsAt;
		}

		public EventPhase getPhase()
		{
			return phase;
		}

		public List<LeaderRow> getTop10()
		{
			return top10;
		}

		public LeaderRow getWinner()
		{
			return winner;
		}

		public long getLastUpdatedEpochMs()
		{
			return lastUpdatedEpochMs;
		}

		public String getCountdownHint()
		{
			return countdownHint;
		}
	}

	public static EventPhase phaseFor(Instant start, Instant end, Instant now)
	{
		if (start == null || end == null)
		{
			return EventPhase.UNKNOWN;
		}
		if (now.isBefore(start))
		{
			return EventPhase.UPCOMING;
		}
		if (now.isAfter(end))
		{
			return EventPhase.FINISHED;
		}
		return EventPhase.ACTIVE;
	}

	public static String formatCountdown(Instant start, Instant end, Instant now, EventPhase phase)
	{
		if (phase == EventPhase.UNKNOWN)
		{
			return "Schedule: —";
		}
		if (phase == EventPhase.UPCOMING)
		{
			return "Starts in " + humanDuration(now, start);
		}
		if (phase == EventPhase.ACTIVE)
		{
			return "Ends in " + humanDuration(now, end);
		}
		return "Ended";
	}

	private static String humanDuration(Instant from, Instant to)
	{
		long seconds = Math.max(0, to.getEpochSecond() - from.getEpochSecond());
		long d = seconds / 86400;
		long h = (seconds % 86400) / 3600;
		long m = (seconds % 3600) / 60;
		long s = seconds % 60;
		if (d > 0)
		{
			return String.format(Locale.US, "%dd %02dh %02dm", d, h, m);
		}
		if (h > 0)
		{
			return String.format(Locale.US, "%dh %02dm %02ds", h, m, s);
		}
		if (m > 0)
		{
			return String.format(Locale.US, "%dm %02ds", m, s);
		}
		return String.format(Locale.US, "%ds", s);
	}

	public static List<LeaderRow> topNFromParticipations(List<WomJson.Participation> participations, int n)
	{
		if (participations == null || participations.isEmpty())
		{
			return Collections.emptyList();
		}
		List<WomJson.Participation> sorted = new ArrayList<>(participations);
		sorted.sort(Comparator.comparingLong((WomJson.Participation p) -> p.progress != null ? p.progress.gainedLong() : 0L).reversed());
		List<LeaderRow> out = new ArrayList<>(Math.min(n, sorted.size()));
		for (int i = 0; i < sorted.size() && i < n; i++)
		{
			WomJson.Participation p = sorted.get(i);
			String name = p.player != null ? coalesce(p.player.displayName, p.player.username, "?") : "?";
			long g = p.progress != null ? p.progress.gainedLong() : 0L;
			String tip = buildTooltip(p);
			out.add(new LeaderRow(i + 1, name, g, tip));
		}
		return Collections.unmodifiableList(out);
	}

	private static String coalesce(String a, String b, String d)
	{
		if (a != null && !a.isEmpty())
		{
			return a;
		}
		if (b != null && !b.isEmpty())
		{
			return b;
		}
		return d;
	}

	private static String buildTooltip(WomJson.Participation p)
	{
		if (p.player == null)
		{
			return "";
		}
		return String.format(Locale.US, "Total XP: %s | EHP: %.2f | EHB: %.2f",
			formatLong(p.player.exp), p.player.ehp, p.player.ehb);
	}

	private static String formatLong(long v)
	{
		return String.format(Locale.US, "%,d", v);
	}
}

package com.terpinheimer.wom;

import com.terpinheimer.TerpinheimerLinks;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.time.Instant;
import java.util.Arrays;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.function.Predicate;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;
import net.runelite.client.RuneLiteProperties;

@Singleton
public class WomCompetitionService
{
	private static final String API = TerpinheimerLinks.WOM_API_BASE;
	private final OkHttpClient http;
	private final Gson gson;

	@Inject
	public WomCompetitionService(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	/**
	 * Resolve competition id, then fetch full leaderboard.
	 * <p>
	 * When {@code autoPick} is true and {@code configuredId} is 0: first tries the configured
	 * metric, then falls back to competitions whose title looks like Skill of the Week (when
	 * {@code rotatingEventIsBossWeek} is false) or Boss of the Week (when true).
	 */
	public WomLeaderboardModels.CompetitionSnapshot fetchSnapshot(
		int groupId, int configuredId, boolean autoPick, String metric,
		String fallbackStartIso, String fallbackEndIso,
		boolean rotatingEventIsBossWeek) throws IOException
	{
		long now = System.currentTimeMillis();
		long resolvedId = configuredId;
		if (resolvedId <= 0 && autoPick && groupId > 0)
		{
			List<WomJson.CompetitionSummary> list = fetchGroupCompetitions(groupId);
			if (list != null && !list.isEmpty())
			{
				if (metric != null && !metric.isEmpty())
				{
					resolvedId = pickFromMatchList(filterSummaries(list, c -> metricEquals(c, metric)));
				}
				if (resolvedId <= 0)
				{
					resolvedId = pickFromMatchList(
						filterSummaries(list, c -> titleMatchesRotatingEvent(c.title, rotatingEventIsBossWeek)));
				}
			}
		}
		if (resolvedId <= 0)
		{
			return buildFallbackSnapshot(fallbackStartIso, fallbackEndIso,
				"Set your WOM group ID in plugin settings, or add a group competition whose title includes SOTW / Skill of the Week or BOTW / Boss of the Week.",
				now);
		}

		WomJson.CompetitionDetails details = fetchCompetitionDetails(resolvedId);
		if (details == null)
		{
			return WomLeaderboardModels.CompetitionSnapshot.error("Data unavailable (empty response)");
		}

		Instant start = parseIso(details.startsAt);
		Instant end = parseIso(details.endsAt);
		Instant nowInst = Instant.now();
		WomLeaderboardModels.EventPhase phase = WomLeaderboardModels.phaseFor(start, end, nowInst);
		List<WomLeaderboardModels.LeaderRow> top = WomLeaderboardModels.topNFromParticipations(details.participations, 10);
		WomLeaderboardModels.LeaderRow winner = null;
		if (phase == WomLeaderboardModels.EventPhase.FINISHED && !top.isEmpty())
		{
			winner = top.get(0);
		}

		String countdown = WomLeaderboardModels.formatCountdown(start, end, nowInst, phase);
		return WomLeaderboardModels.CompetitionSnapshot.ok(
			details.id,
			details.title != null ? details.title : "",
			details.metric != null ? details.metric : "",
			start,
			end,
			phase,
			top,
			winner,
			now,
			countdown
		);
	}

	private WomLeaderboardModels.CompetitionSnapshot buildFallbackSnapshot(String startIso, String endIso, String hint, long nowMs)
	{
		Instant start = parseIsoLenient(startIso);
		Instant end = parseIsoLenient(endIso);
		if (start != null && end != null)
		{
			WomLeaderboardModels.EventPhase ph = WomLeaderboardModels.phaseFor(start, end, Instant.now());
			String cd = WomLeaderboardModels.formatCountdown(start, end, Instant.now(), ph);
			return WomLeaderboardModels.CompetitionSnapshot.ok(0L, "(not linked)", "", start, end, ph,
				java.util.Collections.emptyList(), null, nowMs, cd);
		}
		return WomLeaderboardModels.CompetitionSnapshot.empty(hint);
	}

	private static boolean metricEquals(WomJson.CompetitionSummary c, String metric)
	{
		if (metric == null || metric.isEmpty() || c.metric == null)
		{
			return false;
		}
		return c.metric.toLowerCase(Locale.ROOT).equals(metric.toLowerCase(Locale.ROOT));
	}

	/**
	 * Matches common clan naming: SOTW / Skill of the Week, BOTW / Boss of the Week (legacy BOM).
	 */
	private static boolean titleMatchesRotatingEvent(String title, boolean bossWeek)
	{
		if (title == null)
		{
			return false;
		}
		String t = title.toLowerCase(Locale.ROOT);
		if (bossWeek)
		{
			return t.contains("botw") || t.contains("boss of the week")
				|| t.contains("boss of the month") || t.contains("botm");
		}
		return t.contains("sotw") || t.contains("skill of the week");
	}

	private static List<WomJson.CompetitionSummary> filterSummaries(
		List<WomJson.CompetitionSummary> list, Predicate<WomJson.CompetitionSummary> pred)
	{
		List<WomJson.CompetitionSummary> out = new ArrayList<>();
		for (WomJson.CompetitionSummary c : list)
		{
			if (pred.test(c))
			{
				out.add(c);
			}
		}
		return out;
	}

	private long pickFromMatchList(List<WomJson.CompetitionSummary> match)
	{
		if (match.isEmpty())
		{
			return 0L;
		}
		Instant now = Instant.now();
		for (WomJson.CompetitionSummary c : match)
		{
			Instant s = parseIso(c.startsAt);
			Instant e = parseIso(c.endsAt);
			if (s != null && e != null && !now.isBefore(s) && !now.isAfter(e))
			{
				return c.id;
			}
		}
		List<WomJson.CompetitionSummary> upcoming = new ArrayList<>();
		for (WomJson.CompetitionSummary c : match)
		{
			Instant s = parseIso(c.startsAt);
			if (s != null && now.isBefore(s))
			{
				upcoming.add(c);
			}
		}
		if (!upcoming.isEmpty())
		{
			upcoming.sort(Comparator.comparing(c -> parseIso(c.startsAt), Comparator.nullsLast(Comparator.naturalOrder())));
			return upcoming.get(0).id;
		}
		match.sort(Comparator.comparing(c -> parseIso(c.endsAt), Comparator.nullsLast(Comparator.reverseOrder())));
		return match.get(0).id;
	}

	private List<WomJson.CompetitionSummary> fetchGroupCompetitions(int groupId) throws IOException
	{
		HttpUrl url = HttpUrl.parse(API + "/groups/" + groupId + "/competitions").newBuilder()
			.addQueryParameter("limit", "100")
			.build();
		String rl = RuneLiteProperties.getVersion();
		String ua = "Terpinheimer/2.0.0 RuneLite/" + (rl != null ? rl : "unknown");
		Request req = new Request.Builder().url(url)
			.header("Accept", "application/json")
			.header("User-Agent", ua)
			.build();
		try (Response res = http.newCall(req).execute())
		{
			if (!res.isSuccessful())
			{
				return null;
			}
			ResponseBody body = res.body();
			if (body == null)
			{
				return null;
			}
			try
			{
				WomJson.CompetitionSummary[] arr = gson.fromJson(body.charStream(), WomJson.CompetitionSummary[].class);
				if (arr == null)
				{
					return null;
				}
				return Arrays.asList(arr);
			}
			catch (JsonSyntaxException e)
			{
				return null;
			}
		}
	}

	private WomJson.CompetitionDetails fetchCompetitionDetails(long id) throws IOException
	{
		HttpUrl url = HttpUrl.parse(API + "/competitions/" + id);
		String rl = RuneLiteProperties.getVersion();
		String ua = "Terpinheimer/2.0.0 RuneLite/" + (rl != null ? rl : "unknown");
		Request req = new Request.Builder().url(url)
			.header("Accept", "application/json")
			.header("User-Agent", ua)
			.build();
		try (Response res = http.newCall(req).execute())
		{
			if (!res.isSuccessful())
			{
				return null;
			}
			ResponseBody body = res.body();
			if (body == null)
			{
				return null;
			}
			try
			{
				return gson.fromJson(body.charStream(), WomJson.CompetitionDetails.class);
			}
			catch (JsonSyntaxException e)
			{
				return null;
			}
		}
	}

	private static Instant parseIso(String iso)
	{
		if (iso == null || iso.isEmpty())
		{
			return null;
		}
		try
		{
			return Instant.parse(iso);
		}
		catch (DateTimeParseException e)
		{
			return null;
		}
	}

	private static Instant parseIsoLenient(String iso)
	{
		return parseIso(iso);
	}

}

