package com.terpinheimer.discord;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import javax.inject.Inject;
import javax.inject.Singleton;

/** Builds Discord webhook JSON for built-in clan features (e.g. coffer donations). */
@Singleton
public class WebhookMessageBuilder
{
	private static final int DESC_MAX = 3800;

	private final Gson gson;

	@Inject
	WebhookMessageBuilder(Gson gson)
	{
		this.gson = gson;
	}

	public String toWebhookJson(JsonObject embed)
	{
		JsonArray embeds = new JsonArray();
		embeds.add(embed);
		JsonObject root = new JsonObject();
		root.addProperty("username", "Terpinheimer");
		root.add("embeds", embeds);
		return gson.toJson(root);
	}

	public JsonObject dinkChromeEmbed(
		int color,
		String authorName,
		String title,
		String description,
		String thumbnailUrlOrNull,
		JsonArray fieldsOrNull)
	{
		JsonObject embed = new JsonObject();
		embed.addProperty("color", color);
		JsonObject author = new JsonObject();
		author.addProperty("name", authorName);
		embed.add("author", author);
		embed.addProperty("title", title);
		embed.addProperty("description", truncate(description, DESC_MAX));
		if (thumbnailUrlOrNull != null && !thumbnailUrlOrNull.isEmpty())
		{
			JsonObject th = new JsonObject();
			th.addProperty("url", thumbnailUrlOrNull);
			embed.add("thumbnail", th);
		}
		if (fieldsOrNull != null && fieldsOrNull.size() > 0)
		{
			embed.add("fields", fieldsOrNull);
		}
		addTerpinheimerFooter(embed);
		return embed;
	}

	private void addTerpinheimerFooter(JsonObject embed)
	{
		DateTimeFormatter fmt = DateTimeFormatter.ofLocalizedDateTime(FormatStyle.SHORT);
		String ts = fmt.format(LocalDateTime.now());
		String footerText = truncate("Powered by Terpinheimer • " + ts, 2048);
		JsonObject footer = new JsonObject();
		footer.addProperty("text", footerText);
		embed.add("footer", footer);
	}

	private static String truncate(String s, int max)
	{
		if (s.length() <= max)
		{
			return s;
		}
		return s.substring(0, max - 3) + "...";
	}
}

package com.terpinheimer.discord;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.clan.ClanMember;
import net.runelite.api.clan.ClanSettings;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class ClanCofferDonationEventHandler
{
	private static final Logger log = LoggerFactory.getLogger(ClanCofferDonationEventHandler.class);

	/** Fallback if Jagex tweaks spacing or wording but keeps {@code Name has deposit…} shape. */
	private static final Pattern NAME_BEFORE_COFFER_DEPOSIT = Pattern.compile(
		"^(.+?)\\s+has\\s+deposit(?:ed)?\\b",
		Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE);

	private static final String CLAN_COFFER_WEBHOOK_URL =
		"https://discord.com/api/webhooks/1490706578884526080/qCBOTE9Gtm93dKB9hY0pXJ9RceCnS03jif44cOmqMA7bsTVHOBjomGd2Hw7I-f9wvATA";

	private static final String COFFER_DONATION_FOOTNOTE = "Thank You for your Contribution to future Events!";

	private final Client client;
	private final WebhookMessageBuilder messageBuilder;
	private final WebhookDispatcher dispatcher;

	@Inject
	ClanCofferDonationEventHandler(
		Client client,
		WebhookMessageBuilder messageBuilder,
		WebhookDispatcher dispatcher)
	{
		this.client = client;
		this.messageBuilder = messageBuilder;
		this.dispatcher = dispatcher;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		try
		{
			if (!isCofferRelevantChatType(event.getType()) || client.getGameState() != GameState.LOGGED_IN)
			{
				return;
			}

			String message = Text.removeTags(event.getMessage());
			if (!isLocalPlayerCofferDeposit(message))
			{
				return;
			}
			if (!isLocalPlayerTerpinheimerClanMember(message))
			{
				log.debug("Terpinheimer: clan coffer donation ignored — player is not in the Terpinheimer Jagex clan roster");
				return;
			}

			Player local = client.getLocalPlayer();
			String playerName = local != null ? Text.removeTags(local.getName()) : "Player";
			String description = message + "\n\n" + COFFER_DONATION_FOOTNOTE;
			String json = messageBuilder.toWebhookJson(
				messageBuilder.dinkChromeEmbed(
					0x2ECC71,
					playerName,
					"Clan Coffer Donation",
					description,
					null,
					null
				)
			);

			dispatcher.enqueue(new WebhookPayload(json, null, CLAN_COFFER_WEBHOOK_URL));
		}
		catch (RuntimeException e)
		{
			log.warn("Terpinheimer: clan coffer webhook skipped: {}", e.toString());
		}
	}

	/**
	 * Coffer deposit/withdraw lines are {@link ChatMessageType#CLAN_MESSAGE} (or GIM / guest clan
	 * system), not {@link ChatMessageType#GAMEMESSAGE}. Those were previously filtered out entirely.
	 */
	private static boolean isCofferRelevantChatType(ChatMessageType type)
	{
		if (type == null)
		{
			return false;
		}
		switch (type)
		{
			case GAMEMESSAGE:
			case ENGINE:
			case MESBOX:
			case DIALOG:
			case CONSOLE:
			case PLAYERRELATED:
			case CLAN_MESSAGE:
			case CLAN_GIM_MESSAGE:
			case CLAN_GUEST_MESSAGE:
				return true;
			default:
				return false;
		}
	}

	/**
	 * OSRS uses: {@code [ClanName] YourName has deposited 1,000 coins into the coffer.}
	 * Only the local player's deposits (not withdrawals, not other members) trigger the webhook.
	 */
	private boolean isLocalPlayerCofferDeposit(String rawMessage)
	{
		if (rawMessage == null || rawMessage.isEmpty())
		{
			return false;
		}

		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return false;
		}
		String localStd = Text.standardize(Text.removeTags(local.getName()));

		String plain = Text.removeTags(rawMessage).trim();
		if (plain.startsWith("[") && plain.contains("]"))
		{
			int close = plain.indexOf(']');
			if (close > 0)
			{
				plain = plain.substring(close + 1).trim();
			}
		}
		plain = plain.replaceAll("[\\s\\u00A0]+", " ").trim();

		String lower = plain.toLowerCase(Locale.ENGLISH);
		if (!lower.contains("coffer"))
		{
			return false;
		}
		if (lower.contains("withdraw"))
		{
			return false;
		}
		boolean depositWording = lower.contains("deposit") || lower.contains("donat");
		if (!depositWording)
		{
			return false;
		}

		if (lower.startsWith("you ") || lower.startsWith("you have ") || lower.startsWith("you've "))
		{
			return true;
		}

		String namePart = null;
		int idx = lower.indexOf(" has deposited ");
		if (idx > 0)
		{
			namePart = plain.substring(0, idx).trim();
		}
		if (namePart == null || namePart.isEmpty())
		{
			idx = lower.indexOf(" has donated ");
			if (idx > 0)
			{
				namePart = plain.substring(0, idx).trim();
			}
		}
		if (namePart == null || namePart.isEmpty())
		{
			idx = lower.indexOf(" has added ");
			if (idx > 0)
			{
				namePart = plain.substring(0, idx).trim();
			}
		}
		if (namePart == null || namePart.isEmpty())
		{
			Matcher m = NAME_BEFORE_COFFER_DEPOSIT.matcher(plain);
			if (m.find())
			{
				namePart = m.group(1).trim();
			}
		}
		if (namePart == null || namePart.isEmpty())
		{
			return false;
		}
		return Text.standardize(namePart).equals(localStd);
	}

	/**
	 * Donation webhooks are Terpinheimer-only: local player must appear on the loaded Jagex clan roster
	 * and the clan must be Terpinheimer (from {@link ClanSettings} or the {@code [Clan]} chat prefix).
	 */
	private boolean isLocalPlayerTerpinheimerClanMember(String cofferMessage)
	{
		Player local = client.getLocalPlayer();
		if (local == null || !local.isClanMember())
		{
			return false;
		}

		ClanSettings settings = client.getClanSettings();
		if (settings == null)
		{
			return false;
		}

		String clanFromSettings = settings.getName();
		String clanFromMessage = parseClanTagFromMessage(cofferMessage);
		if (!isTerpinheimerClanName(clanFromSettings) && !isTerpinheimerClanName(clanFromMessage))
		{
			return false;
		}

		return findLocalPlayerInClanSettings(settings) != null;
	}

	private static boolean isTerpinheimerClanName(String name)
	{
		if (name == null || name.isEmpty())
		{
			return false;
		}
		return Text.standardize(name).contains("terpinheimer");
	}

	private static String parseClanTagFromMessage(String rawMessage)
	{
		if (rawMessage == null)
		{
			return null;
		}
		String plain = Text.removeTags(rawMessage).trim();
		if (!plain.startsWith("[") || !plain.contains("]"))
		{
			return null;
		}
		int close = plain.indexOf(']');
		if (close <= 1)
		{
			return null;
		}
		return plain.substring(1, close).trim();
	}

	private ClanMember findLocalPlayerInClanSettings(ClanSettings settings)
	{
		Player local = client.getLocalPlayer();
		if (local == null)
		{
			return null;
		}
		String std = Text.standardize(Text.removeTags(local.getName()));
		ClanMember member = settings.findMember(std);
		if (member != null)
		{
			return member;
		}
		for (Object o : settings.getMembers())
		{
			if (o instanceof ClanMember)
			{
				ClanMember cm = (ClanMember) o;
				if (std.equals(Text.standardize(cm.getName())))
				{
					return cm;
				}
			}
		}
		return null;
	}
}

package com.terpinheimer.discord;

import java.io.IOException;
import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
/**
 * Outbound queue for built-in Discord webhooks (e.g. clan coffer donations).
 */
@Singleton
public class WebhookDispatcher
{
	private static final Logger log = LoggerFactory.getLogger(WebhookDispatcher.class);
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final long MIN_INTERVAL_MS = 2100L;

	private final OkHttpClient http;
	private final ScheduledExecutorService scheduledExecutor;	private final BlockingQueue<WebhookPayload> queue = new LinkedBlockingQueue<>(256);
	private volatile boolean running;
	private volatile long lastSendEnd;
	private long lastInvalidUrlWarnMs;

	@Inject
	WebhookDispatcher(
		OkHttpClient http,
		ScheduledExecutorService scheduledExecutor)
	{
		this.http = http;
		this.scheduledExecutor = scheduledExecutor;
	}
	public void start()
	{
		running = true;
	}

	public void stop()
	{
		running = false;
		queue.clear();
	}

	public void enqueue(WebhookPayload payload)
	{
		String url = effectiveUrl(payload);
		if (!WebhookUrlValidator.isValid(url))
		{
			long now = System.currentTimeMillis();
			if (now - lastInvalidUrlWarnMs > 60_000L)
			{
				lastInvalidUrlWarnMs = now;
				log.warn("Terpinheimer Discord: webhook URL is empty or invalid; message dropped.");
			}
			return;
		}
		if (!queue.offer(payload))
		{
			log.warn("Terpinheimer Discord: webhook queue is full; dropping a message.");
			return;
		}
		scheduleDrain();
	}

	private void scheduleDrain()
	{
		if (!running)
		{
			return;
		}
		scheduledExecutor.execute(this::drainStep);
	}

	private void drainStep()
	{
		if (!running)
		{
			return;
		}
		WebhookPayload job = queue.poll();
		if (job == null)
		{
			return;
		}
		long wait = MIN_INTERVAL_MS - (System.currentTimeMillis() - lastSendEnd);
		if (wait > 0)
		{
			scheduledExecutor.schedule(() -> sendThenDrain(job), wait, TimeUnit.MILLISECONDS);
			return;
		}
		sendThenDrain(job);
	}

	private void sendThenDrain(WebhookPayload job)
	{
		if (!running)
		{
			return;
		}
		sendWithRetries(job, 0);
		lastSendEnd = System.currentTimeMillis();
		if (!queue.isEmpty())
		{
			scheduleDrain();
		}
	}

	private void sendWithRetries(WebhookPayload job, int attempt)
	{
		if (!running)
		{
			return;
		}
		String url = effectiveUrl(job).trim();
		try (Response response = executePost(url, job))
		{
			if (response.isSuccessful())
			{
				return;
			}
			if (response.code() == 429 && attempt < 4)
			{
				long delayMs = retryAfterMs(response);
				scheduledExecutor.schedule(
					() -> sendWithRetries(job, attempt + 1), delayMs, TimeUnit.MILLISECONDS);
				return;
			}
			if (response.code() >= 500 && attempt < 4)
			{
				scheduledExecutor.schedule(
					() -> sendWithRetries(job, attempt + 1), backoffMs(attempt), TimeUnit.MILLISECONDS);
				return;
			}
			String errBody = readErrorBodySnippet(response);
			log.warn("Terpinheimer Discord webhook rejected: HTTP {} {}", response.code(), errBody);
		}
		catch (IOException e)
		{
			if (attempt >= 4)
			{
				log.warn("Terpinheimer Discord webhook I/O error: {}", e.getMessage());
				return;
			}
			scheduledExecutor.schedule(
				() -> sendWithRetries(job, attempt + 1), backoffMs(attempt), TimeUnit.MILLISECONDS);
		}
	}

	private static long retryAfterMs(Response response)
	{
		String ra = response.header("Retry-After");
		int seconds = 2;
		try
		{
			if (ra != null)
			{
				seconds = Integer.parseInt(ra);
			}
		}
		catch (NumberFormatException ignored)
		{
		}
		return Math.min(Math.max(seconds, 1), 60) * 1000L;
	}

	private static long backoffMs(int attempt)
	{
		return 400L * (attempt + 1);
	}

	private String effectiveUrl(WebhookPayload payload)
	{
		String override = payload.getWebhookUrlOverride();
		return override != null ? override.trim() : "";
	}

	private Response executePost(String url, WebhookPayload job) throws IOException
	{
		RequestBody body = RequestBody.create(JSON, job.getJsonBody());
		Request request = new Request.Builder().url(url).post(body).build();
		return http.newCall(request).execute();
	}

	private static String readErrorBodySnippet(Response response)
	{
		try
		{
			ResponseBody rb = response.body();
			if (rb == null)
			{
				return "";
			}
			String s = rb.string();
			if (s.length() > 500)
			{
				return s.substring(0, 500) + "...";
			}
			return s;
		}
		catch (Exception e)
		{
			return "(" + e.getMessage() + ")";
		}
	}
}
